66	/// A symbol as another response embeds it: the id, and the node id of the file that owns it. The full symbol is one
67	/// call away (`getSymbolOfType`, `getAliasSymbolOfType`).
68	#[derive(Debug, Clone, PartialEq, Eq, Hash, Deserialize)]
69	pub(crate) struct CompactSymbol {
70	    pub id: u64,
71	    #[serde(default)]
72	    pub file: Option<String>,
73	}
74	
75	/// The checker keeps a symbol's name in an escaped form: a name that starts with two underscores gets a third
76	/// (`escapeLeadingUnderscores`), so that it cannot collide with its own internal names such as `__call`. The source
77	/// writes `__size`, the checker answers `___size`. A name with fewer than three leading underscores is unchanged, and
78	/// so are the internal names, which start with exactly two.
79	pub(crate) fn unescape_leading_underscores(name: &str) -> &str {
80	    if name.starts_with("___") { name.strip_prefix('_').unwrap_or(name) } else { name }
81	}
82	
83	fn unescaped_name<'de, D: serde::Deserializer<'de>>(deserializer: D) -> Result<String, D::Error> {
84	    let name = String::deserialize(deserializer)?;
85	    Ok(unescape_leading_underscores(&name).to_string())
86	}
