89	#[serde(rename_all = "camelCase")]
90	pub(crate) struct TypeInfo {
91	    pub id: u64,
92	    pub flags: u64,
93	    #[serde(default)]
94	    pub object_flags: u64,
95	    #[serde(default)]
96	    pub value: Option<Value>,
97	    #[serde(default)]
98	    pub is_tuple_type: bool,
99	    /// The checker's name for an intrinsic type (`"any"`, `"string"`, `"error"`). It alone tells a written `any` from
100	    /// the error type of an unresolved name: both carry the `Any` flag, and the error type has an id per site.
101	    #[serde(default)]
102	    pub intrinsic_name: Option<String>,
103	    /// `TupleElementFlags` of a tuple type's elements: required 1, optional 2, rest 4, variadic 8.
104	    #[serde(default)]
105	    pub element_flags: Vec<u64>,
106	    /// A tuple type written `readonly [...]`.
107	    #[serde(default)]
108	    pub readonly: bool,
109	    /// One declaration handle per element of a tuple whose elements are labeled, `[head: string]`; empty otherwise.
110	    #[serde(default)]
111	    pub labeled_element_declarations: Vec<String>,
112	    /// The text pieces of a template literal type, around its holes.
113	    #[serde(default)]
114	    pub texts: Vec<String>,
115	    /// The `this` type of a class or interface, which the checker also appends to a reference's type arguments.
116	    #[serde(default)]
117	    pub is_this_type: bool,
118	    /// The symbol that declares an object type; absent for primitives and unions.
119	    #[serde(default)]
120	    pub symbol: Option<CompactSymbol>,
121	    /// The alias this type was written through, `Size` in `type Size = "sm" | "lg"`.
122	    #[serde(default)]
123	    pub alias_symbol: Option<CompactSymbol>,
124	    /// Ids of the alias's type arguments; `Rpc::alias_type_arguments` fetches them.
125	    #[serde(default)]
126	    pub alias_type_arguments: Vec<u64>,
127	    /// The keys a mapped type ranges over (`keyof Conditions` in `{ [K in keyof Conditions]?: V }`), as the checker's
128	    /// type handle; absent for a type that is not a mapped type.
129	    #[serde(default)]
130	    pub constraint_type: Option<u64>,
131	    /// The `as` clause of a mapped type, which renames its keys; absent when it has none.
132	    #[serde(default)]
133	    pub name_type: Option<u64>,
134	}
