564	    /// The type a type parameter defaults to (`"div"` in `E extends ElementType = "div"`); none when it declares none.
565	    pub(crate) async fn default_of_type_parameter(&self, type_id: u64) -> Result<Option<TypeInfo>, CallError> {
566	        self.scoped("getDefaultFromTypeParameter", json!({ "objectId": type_id })).await
