574	    /// The type errors in a file of the program.
575	    pub(crate) async fn semantic_diagnostics(&self, file: &str) -> Result<Vec<FileDiagnostic>, CallError> {
576	        self.scoped("getSemanticDiagnostics", json!({ "file": file })).await
577	    }
578	
579	    /// The symbol that declares a type: the interface, class, enum member or unique symbol behind it.
580	    pub(crate) async fn symbol_of_type(&self, type_id: u64) -> Result<Option<SymbolInfo>, CallError> {
581	        self.scoped("getSymbolOfType", json!({ "objectId": type_id })).await
582	    }
583	
584	    /// The types a class or interface extends, instantiated as it names them (`Omit<HTMLAttributes<HTMLDivElement>, "color">`);
585	    /// none for a type that is not a class or interface.
586	    pub(crate) async fn base_types(&self, type_id: u64) -> Result<Vec<TypeInfo>, CallError> {
587	        let bases: Option<Vec<TypeInfo>> = self.scoped("getBaseTypes", json!({ "type": type_id })).await?;
588	        Ok(bases.unwrap_or_default())
589	    }
590	
591	    pub(crate) async fn alias_type_arguments(&self, type_id: u64) -> Result<Vec<TypeInfo>, CallError> {
592	        self.scoped("getAliasTypeArgumentsOfType", json!({ "objectId": type_id })).await
593	    }
594	
595	    /// The generic type a reference instantiates; for a tuple reference, the tuple type that holds its element flags.
596	    pub(crate) async fn target_of_type(&self, type_id: u64) -> Result<TypeInfo, CallError> {
597	        self.scoped("getTargetOfType", json!({ "objectId": type_id })).await
598	    }
599	
600	    pub(crate) async fn parent_of_symbol(&self, symbol: &Value) -> Result<Option<SymbolInfo>, CallError> {
601	        self.scoped("getParentOfSymbolForChecker", json!({ "symbol": symbol })).await
602	    }
603	
604	    /// Whether each property is declared `readonly`, in one round trip.
605	    pub(crate) async fn readonly_symbols(&self, symbols: &[&Value]) -> Result<Vec<bool>, CallError> {
606	        let requests = symbols.iter().map(|symbol| ("isReadonlySymbol", json!({ "symbol": symbol }))).collect();
607	        self.batch(requests).await?.iter().map(|answer| decode(answer)).collect()
608	    }
609	
610	    /// Several requests in one round trip. A request the checker rejects fails the batch: nothing here asks for one
611	    /// that may legitimately fail.
612	    pub(crate) async fn batch(&self, requests: Vec<(&str, Value)>) -> Result<Vec<Box<RawValue>>, CallError> {
613	        let wanted = requests.len();
614	        let scoped: Vec<Value> = requests
615	            .into_iter()
616	            .map(|(method, mut params)| {
617	                if let Value::Object(map) = &mut params {
618	                    map.insert("snapshot".to_string(), json!(self.snapshot));
619	                    map.insert("project".to_string(), json!(self.project));
620	                }
621	                json!({ "method": method, "params": params })
622	            })
623	            .collect();
624	        let mut answers = Vec::with_capacity(wanted);
625	        let mut token: Option<String> = None;
626	        loop {
627	            let mut params = json!({ "requests": scoped });
628	            if let (Some(token), Some(map)) = (&token, params.as_object_mut()) {
629	                map.insert("continuationToken".to_string(), json!(token));
630	            }
631	            let page: BatchPage = decode(&self.call("batchRequests", params).await?)?;
632	            for response in page.responses {
633	                if let Some(error) = response.error {
634	                    return Err(CallError::Rejected(error));
635	                }
636	                answers.push(response.result.unwrap_or_else(|| RawValue::NULL.to_owned()));
637	            }
638	            match page.continuation_token {
639	                Some(next) => token = Some(next),
640	                None => break,
641	            }
642	        }
643	        if answers.len() != wanted {
644	            return Err(CallError::Rejected(format!("a batch of {wanted} requests got {} answers", answers.len())));
645	        }
646	        Ok(answers)
647	    }
648	
649	    pub(crate) async fn parameters(&self, signature: u64) -> Result<Vec<SymbolInfo>, CallError> {
650	        self.scoped("getParametersOfSignature", json!({ "objectId": signature })).await
651	    }
652	
653	    pub(crate) async fn return_type(&self, signature: u64) -> Result<TypeInfo, CallError> {
654	        self.scoped("getReturnTypeOfSignature", json!({ "objectId": signature })).await
655	    }
656	
657	    pub(crate) async fn properties(&self, type_id: u64) -> Result<Vec<SymbolInfo>, CallError> {
658	        self.scoped("getPropertiesOfType", json!({ "type": type_id })).await
659	    }
660	
661	    /// The members of a union, intersection or template literal, as the text the checker answered (a list of types).
662	    pub(crate) async fn members_text(&self, type_id: u64) -> Result<Box<RawValue>, CallError> {
663	        self.scoped_text("getTypesOfType", json!({ "objectId": type_id })).await
664	    }
665	
666	    /// The type arguments of a reference, as the text the checker answered (a list of types).
667	    pub(crate) async fn type_arguments_text(&self, type_id: u64) -> Result<Box<RawValue>, CallError> {
668	        self.scoped_text("getTypeArguments", json!({ "type": type_id })).await
669	    }
670	
671	    /// The call and construct signatures, the properties and the index signatures of a type, in one round trip.
672	    pub(crate) async fn object_members(&self, type_id: u64) -> Result<ObjectMembers, CallError> {
673	        let requests = vec![
674	            ("getSignaturesOfType", json!({ "type": type_id, "kind": SignatureKind::Call as u8 })),
675	            ("getSignaturesOfType", json!({ "type": type_id, "kind": SignatureKind::Construct as u8 })),
676	            ("getPropertiesOfType", json!({ "type": type_id })),
677	            ("getIndexInfosOfType", json!({ "type": type_id })),
678	        ];
679	        let mut answers = self.batch(requests).await?.into_iter();
680	        let mut next = || answers.next().ok_or_else(|| CallError::Rejected("a short batch".to_string()));
681	        Ok(ObjectMembers {
682	            calls: decode(&next()?)?,
683	            constructs: decode(&next()?)?,
684	            properties: decode(&next()?)?,
685	            indexes: decode(&next()?)?,
686	        })
687	    }
688	
689	    pub(crate) async fn alias_symbol(&self, type_id: u64) -> Result<Option<SymbolInfo>, CallError> {
690	        self.scoped("getAliasSymbolOfType", json!({ "objectId": type_id })).await
691	    }
692	
693	    pub(crate) async fn type_to_string(&self, type_id: u64) -> Result<String, CallError> {
694	        self.scoped("typeToString", json!({ "type": type_id })).await
695	    }
696	
697	    /// The type as written inside a type alias declaration, and never cut short: an alias at the top is printed as what
698	    /// it stands for (`(value?: string) => void`, not `Handler`), and a long type is printed to its end.
699	    pub(crate) async fn type_to_string_expanded(&self, type_id: u64) -> Result<String, CallError> {
700	        self.scoped("typeToString", json!({ "type": type_id, "flags": flag::PRINT_EXPANDED })).await
701	    }
702	}
703	
704	fn default_options() -> Value {
705	    // Numeric enum values: JSX preserve, ESNext modules, bundler resolution, ES2022.
706	    json!({ "jsx": 1, "module": 99, "moduleResolution": 100, "target": 9, "strict": true, "skipLibCheck": true, "noEmit": true })
707	}
708	
709	/// An answer parsed from its text straight into `T`, in one pass.
710	pub(crate) fn decode<T: DeserializeOwned>(answer: &RawValue) -> Result<T, CallError> {
711	    serde_json::from_str(answer.get())
712	        .map_err(|error| CallError::Rejected(format!("unexpected response shape: {error}")))
713	}
714	
715	#[cfg(test)]
716	mod tests {
717	    use super::*;
718	
719	    #[test]
720	    fn a_name_with_three_or_more_leading_underscores_loses_the_one_the_checker_added() {
721	        assert_eq!(unescape_leading_underscores("___size"), "__size");
722	        assert_eq!(unescape_leading_underscores("____triple"), "___triple");
723	        assert_eq!(unescape_leading_underscores("___0"), "__0");
724	    }
725	
726	    #[test]
727	    fn other_names_are_unchanged() {
728	        for name in ["size", "_single", "__call", "__type", "default", "", "a___b"] {
729	            assert_eq!(unescape_leading_underscores(name), name);
730	        }
731	    }
732	
733	    #[test]
734	    fn a_symbol_arrives_with_the_name_the_source_writes() {
735	        let symbol: SymbolInfo =
736	            serde_json::from_value(json!({ "reference": {}, "name": "___size", "flags": 0 })).unwrap();
737	
738	        assert_eq!(symbol.name, "__size");
739	    }
740	}
