1	//! The checker a run asks, and the one place that picks which: the `tsrs` crates linked into this process, or a
2	//! `tsc --api` process when an explicit `tsc_path` names one (the Go `typescript@7.1` the tests and the parity gate
3	//! run, or a `tsrs` binary). Both answer the same methods with the same JSON, so [`crate::rpc`] does not know which.
4	//!
5	//! The linked checker answers on threads of its own with a 512 MiB stack, the stack the `tsrs` binary serves on. A
6	//! query runs on the thread that calls it, and a type nested 2,000 deep overflows a default 2 MiB thread: a stack
7	//! overflow aborts the whole process and cannot be caught. Callers on any thread send it requests over a channel, one
8	//! per checker thread (a lane), and each thread answers its own one at a time, in the order they arrive; a run that asks
9	//! several programs at once sends each program's requests down a lane of its own ([`Client::lane`]). A panic inside the
10	//! checker comes back as an error to the request that caused it (`tsrs_api` catches it), and the session keeps
11	//! answering.
12	
13	use std::sync::atomic::{AtomicUsize, Ordering};
14	use std::sync::{Arc, mpsc};
15	use std::thread::JoinHandle;
16	use std::time::Duration;
17	
18	use caliper_docgen_tsc_client::{MalformedFrameReason, Supervisor, SupervisorConfig, TscClientError};
19	use camino::Utf8Path;
20	use serde_json::Value;
21	use serde_json::value::RawValue;
22	use tokio::sync::oneshot;
23	use tsrs_api::{Handler, Response, Session, SessionOptions};
24	use tsrs_vfs::{FS, bundled, osvfs};
25	
26	use crate::locate;
27	
28	/// The stack of the thread the linked checker answers on: what the `tsrs` binary gives each of its threads.
29	const CHECKER_STACK_BYTES: usize = 512 << 20;
30	
31	/// The JSON-RPC code the `tsrs` and `tsc` processes answer a failed request with (`jsonrpc.CodeInternalError`); the
32	/// message is the error's text, as here.
33	const INTERNAL_ERROR: i64 = -32603;
34	
35	/// How to start a checker: an explicit binary runs as a process, none links the bundled one.
36	pub(crate) struct Start<'a> {
37	    pub(crate) project_root: &'a Utf8Path,
38	    pub(crate) tsc_path: Option<&'a Utf8Path>,
39	    pub(crate) expected_versions: &'static [&'static str],
40	    pub(crate) timeout: Duration,
41	    pub(crate) extra_env: &'a [(String, String)],
42	    /// How many threads the linked checker answers on: requests about different programs of its session run at once.
43	    /// A process answers on its own terms.
44	    pub(crate) threads: usize,
45	}
46	
47	/// A running checker.
48	pub(crate) enum Backend {
49	    /// A `tsc --api` process for an explicit binary.
50	    Process(Box<Supervisor>),
51	    /// The checker linked into this process, on its own thread.
52	    InProcess(InProcess),
53	}
54	
55	impl Backend {
56	    /// The checker `start` asks for. An explicit path that does not exist, a binary that does not start or is not a
57	    /// supported version, or a checker thread that cannot be spawned, is an error that says so.
58	    pub(crate) async fn start(start: Start<'_>) -> Result<Backend, String> {
59	        let Some(tsc_path) = start.tsc_path else {
60	            return InProcess::start(start.project_root, start.threads).map(Backend::InProcess);
61	        };
62	        let tsc_path = locate::explicit_tsc(tsc_path)?;
63	        let mut config = SupervisorConfig::new(tsc_path, start.project_root.to_owned(), start.expected_versions);
64	        config.handshake_timeout = start.timeout;
65	        config.extra_env = start.extra_env.to_vec();
66	        Supervisor::spawn(config)
67	            .await
68	            .map(|supervisor| Backend::Process(Box::new(supervisor)))
69	            .map_err(|error| error.to_string())
70	    }
71	
72	    /// How many programs a run asks at once: one per thread of the linked checker, one for a process (whose requests
73	    /// this client sends one at a time).
74	    pub(crate) fn parallel_programs(&self) -> usize {
75	        match self {
76	            Backend::Process(_) => 1,
77	            Backend::InProcess(checker) => checker.threads,
78	        }
79	    }
80	
81	    pub(crate) fn client(&self) -> Client {
82	        match self {
83	            Backend::Process(supervisor) => Client::Process(supervisor.client()),
84	            Backend::InProcess(checker) => Client::InProcess(checker.client.clone()),
85	        }
86	    }
87	
88	    pub(crate) fn is_alive(&self) -> bool {
89	        match self {
90	            Backend::Process(supervisor) => supervisor.is_alive(),
91	            Backend::InProcess(checker) => !checker.thread.is_finished(),
92	        }
93	    }
94	
95	    /// The operating system's id of the checker process; `None` for the linked checker, which is this process.
96	    pub(crate) fn process_id(&self) -> Option<u32> {
97	        match self {
98	            Backend::Process(supervisor) => supervisor.process_id(),
99	            Backend::InProcess(_) => None,
100	        }
101	    }
102	
103	    /// Stops the checker. A process is reaped. The linked checker's thread finishes the request it is in, closes its
104	    /// session and exits on its own: it is not waited for, so a hung request cannot hold the caller.
105	    pub(crate) async fn shutdown(self) {
106	        match self {
107	            Backend::Process(supervisor) => {
108	                if let Err(error) = (*supervisor).shutdown().await {
109	                    tracing::debug!(%error, "the checker process did not shut down cleanly");
110	                }
111	            }
112	            Backend::InProcess(checker) => checker.client.stop(),
113	        }
114	    }
115	}
