117	/// A handle that sends requests to a running checker. Cheap to clone.
118	#[derive(Clone)]
119	pub(crate) enum Client {
120	    Process(caliper_docgen_tsc_client::Client),
121	    InProcess(Linked),
122	}
123	
124	impl Client {
125	    /// The client whose requests the `lane`th thread of the linked checker answers ([`InProcess::start`]); a process
126	    /// has one lane, so its client is itself.
127	    pub(crate) fn lane(&self, lane: usize) -> Client {
128	        match self {
129	            Client::Process(client) => Client::Process(client.clone()),
130	            Client::InProcess(linked) => Client::InProcess(Linked { lanes: linked.lanes.clone(), lane }),
131	        }
132	    }
133	
134	    /// One request, its answer the `result` as the JSON text it arrived as. The wait is bounded by `deadline`; an
135	    /// error is the one the process route would give for the same failure.
136	    pub(crate) async fn request_raw(
137	        &self,
138	        method: &str,
139	        params: Value,
140	        deadline: Duration,
141	    ) -> Result<Box<RawValue>, TscClientError> {
142	        match self {
143	            Client::Process(client) => Ok(client.request_raw(method, params, deadline).await?.result),
144	            Client::InProcess(linked) => linked.request(method, params, deadline).await,
145	        }
146	    }
147	}
