149	/// The linked checker: the thread that owns its session, and the way to it.
150	pub(crate) struct InProcess {
151	    client: Linked,
152	    thread: JoinHandle<()>,
153	    threads: usize,
154	}
155	
156	enum Job {
157	    Request(Asked),
158	    /// Close the session and end the thread; requests sent after it fail as from a stopped checker.
159	    Stop,
160	}
161	
162	struct Asked {
163	    method: String,
164	    params: Vec<u8>,
165	    reply: oneshot::Sender<Result<String, String>>,
166	}
167	
168	/// The sending ends of the linked checker's queues, one per thread, and the one this client sends to.
169	#[derive(Clone)]
170	pub(crate) struct Linked {
171	    lanes: Arc<[mpsc::Sender<Job>]>,
172	    lane: usize,
173	}
174	
175	impl InProcess {
176	    /// Spawns the checker thread, which creates its session there: the session's work, from the first request on,
177	    /// runs on that thread's stack. With `threads` above one it starts as many more, each answering a queue of its own
178	    /// (a lane, [`Client::lane`]) on the same session: requests about one program wait for each other (each program
179	    /// has one checker, which `tsrs_api` locks for the length of a request), so a run that sends the requests about
180	    /// each of its programs down a lane of its own has them answered at once.
181	    pub(crate) fn start(project_root: &Utf8Path, threads: usize) -> Result<InProcess, String> {
182	        let (lanes, queues): (Vec<_>, Vec<_>) = (0..threads.max(1)).map(|_| mpsc::channel()).unzip();
183	        let threads = lanes.len();
184	        let cwd = project_root.to_string();
185	        let thread = std::thread::Builder::new()
186	            .name("caliper-checker".to_string())
187	            .stack_size(CHECKER_STACK_BYTES)
188	            .spawn(move || serve(cwd, queues))
189	            .map_err(|error| format!("could not start the checker thread: {error}"))?;
190	        Ok(InProcess { client: Linked { lanes: lanes.into(), lane: 0 }, thread, threads })
191	    }
192	}
193	
194	impl Linked {
195	    async fn request(&self, method: &str, params: Value, deadline: Duration) -> Result<Box<RawValue>, TscClientError> {
196	        let params = serde_json::to_vec(&params).map_err(|error| TscClientError::Serialize(Arc::new(error)))?;
197	        let (reply, answer) = oneshot::channel();
198	        let asked = Asked { method: method.to_string(), params, reply };
199	        let Some(jobs) = self.lanes.get(self.lane % self.lanes.len().max(1)) else {
200	            return Err(TscClientError::SessionClosed);
201	        };
202	        if jobs.send(Job::Request(asked)).is_err() {
203	            return Err(TscClientError::SessionClosed);
204	        }
205	        let answered = match tokio::time::timeout(deadline, answer).await {
206	            Ok(Ok(answered)) => answered,
207	            // The thread ended without answering: stopped, or its session could not be created.
208	            Ok(Err(_dropped)) => return Err(TscClientError::SessionClosed),
209	            Err(_elapsed) => return Err(TscClientError::Timeout { method: method.to_string(), after: deadline }),
210	        };
211	        match answered {
212	            Ok(text) => RawValue::from_string(text)
213	                .map_err(|_invalid| TscClientError::MalformedFrame { reason: MalformedFrameReason::InvalidJson }),
214	            Err(message) => Err(TscClientError::RpcError { code: INTERNAL_ERROR, message, data: None }),
215	        }
216	    }
217	
218	    fn stop(&self) {
219	        // A thread that already ended has nothing to stop.
220	        for jobs in self.lanes.iter() {
221	            jobs.send(Job::Stop).ok();
222	        }
223	    }
224	}
225	
226	/// The checker threads: one session, each thread answering the requests of its queue in turn until it is stopped or
227	/// every sender is gone. The first thread creates the session and starts the others; the last to leave closes it.
228	fn serve(cwd: String, queues: Vec<mpsc::Receiver<Job>>) {
229	    let fs: Arc<dyn FS> = Arc::new(bundled::wrap_fs(osvfs::fs()));
230	    let session = Session::new(SessionOptions::new(cwd, bundled::lib_path(), fs, false));
231	    let left = Arc::new(AtomicUsize::new(queues.len()));
232	    let mut queues = queues.into_iter();
233	    let Some(own) = queues.next() else { return session.close() };
234	    for (index, queue) in queues.enumerate() {
235	        let (session, still) = (session.clone(), left.clone());
236	        let spawned = std::thread::Builder::new()
237	            .name(format!("caliper-checker-{}", index + 1))
238	            .stack_size(CHECKER_STACK_BYTES)
239	            .spawn(move || answer(&session, queue, &still));
240	        // Its queue is dropped with the closure, so its lane's requests fail as from a stopped checker.
241	        if spawned.is_err() {
242	            left.fetch_sub(1, Ordering::AcqRel);
243	        }
244	    }
245	    answer(&session, own, &left);
246	}
247	
248	/// One checker thread: the requests of `queue` in turn, until it is stopped or every sender is gone. The last thread
249	/// of the session (`left`) closes it.
250	fn answer(session: &Session, queue: mpsc::Receiver<Job>, left: &AtomicUsize) {
251	    for job in queue {
252	        let asked = match job {
253	            Job::Request(asked) => asked,
254	            Job::Stop => break,
255	        };
256	        // A caller that stopped waiting (its deadline passed, its run ended) is not answered.
257	        if asked.reply.is_closed() {
258	            continue;
259	        }
260	        let answer = match session.handle_request(&asked.method, &asked.params) {
261	            Ok(Response::Json(text)) => Ok(text),
262	            Ok(Response::Binary(_)) => Err(format!("{} answered in binary, not JSON", asked.method)),
263	            Err(error) => Err(error.to_string()),
264	        };
265	        asked.reply.send(answer).ok();
266	    }
267	    if left.fetch_sub(1, Ordering::AcqRel) == 1 {
268	        session.close();
269	    }
270	}
